-- Athena saved query (Product_B2C_Intl)
-- ID: dd878989-1fe8-400a-85db-10a8a6814430
-- Name: Train CTR - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH SRP AS ( SELECT -- date_format(__time, '%Y-%b') AS month_period, DATE(DATE_ADD('MINUTE', 330, "__time")) AS doi, is_train_available AS ShowTrainsOnBusSrp, doj, src_id, dest_id, -- 'Any DBD' AS search_day, mri_session_id FROM user_interaction.search_details WHERE __time >= timestamp '2026-04-01 00:00:00' AND __time < timestamp '2026-04-29 00:00:00' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' AND tp_channel = 'INVALID' AND (akamai_bot = '' OR akamai_bot IS NULL) GROUP BY 1,2,3,4,5,6 ), SL AS ( SELECT DATE(DATE_ADD('MINUTE', 330, "__time")) AS doi, src_id, dest_id, mri_session_id, CAST(doj AS DATE) doj FROM user_interaction.seat_layout_details WHERE __time >= timestamp '2026-04-01 00:00:00' AND __time < timestamp '2026-04-29 00:00:00' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' AND tp_channel = 'INVALID' GROUP BY 1, 2, 3, 4, 5 ) SELECT s.doi, CASE WHEN DATE_DIFF('day', s.doi, s.doj) = 0 THEN '0. Same Day' WHEN DATE_DIFF('day', s.doi, s.doj) = 1 THEN '1. DBD 1' WHEN DATE_DIFF('day', s.doi, s.doj) = 2 THEN '2. DBD 2' WHEN DATE_DIFF('day', s.doi, s.doj) > 2 THEN '3. DBD 2+' ELSE 'Others' END AS search_day, COUNT(DISTINCT CASE WHEN ShowTrainsOnBusSrp = True THEN s.mri_session_id END) AS TrainSeenSessions, COUNT(DISTINCT s.mri_session_id) overall_sessions, COUNT(DISTINCT CASE WHEN ShowTrainsOnBusSrp = True THEN sl.mri_session_id END) AS TrainSeenSlLands, COUNT(DISTINCT sl.mri_session_id) overall_sl_lands FROM SRP s LEFT JOIN SL sl ON s.doi = sl.doi AND s.src_id = sl.src_id AND s.dest_id = sl.dest_id AND s.mri_session_id = sl.mri_session_id AND s.doj = sl.doj GROUP BY 1, 2
